using System;
using System.Collections;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Ownership;
using MiniFramework.Accounts;
using MiniFramework.Ads;
using MiniFramework.Platform;
using MiniFramework.Providers.IdentityFake;
using MiniFramework.Providers.AdsMock;
using MiniFramework.Providers.PlatformMock;
using MiniFramework.Providers.StorageFake;
using MiniFramework.Storage;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
public sealed class OwnershipServiceTests
{
    static OperationContext Wait=>OperationContext.Unlimited();static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    static FrameworkError Error(string code,ErrorKind kind=ErrorKind.Provider)=>new FrameworkError(kind,code,"private-message");
    sealed class Generation:IOwnerGenerationSource
    {
        readonly Func<Result<long>> reserve;internal Generation(Func<Result<long>> reserve){this.reserve=reserve;}public Result<long> Reserve()=>reserve();
    }
    sealed class ToggleCleanup:IAsyncCleanup
    {
        public string Id=>"toggle";internal bool Fail=true;internal int Count;
        public UniTask<Result> CleanupAsync(CleanupContext cleanup){Count++;return UniTask.FromResult(Fail?Result.Failure(Error("test.release",ErrorKind.CleanupFailed)):Result.Success());}
    }
    sealed class Env
    {
        internal readonly FakeIdentityProvider Identity=new FakeIdentityProvider();internal readonly MockPlatformBackend PlatformBackend=new MockPlatformBackend();internal readonly MockRewardedAdBackend AdBackend=new MockRewardedAdBackend();
        internal readonly AdReceiptJournal Journal=new AdReceiptJournal();internal readonly List<Action> FinishActions=new List<Action>();internal readonly IClaimOwnerAuthority Authority;
        internal readonly AccountService Account;internal readonly LocalOwnerService Local;internal readonly AdsService Ads;internal readonly GameContext Context;
        internal Env(bool local=false,AccountLimits limits=null,IOwnerGenerationSource generations=null,bool simulated=true,string ownerDependency=null)
        {
            generations=generations??new OwnerGenerationSequence();IModule module;
            if(local){Local=new LocalOwnerService(OwnershipPolicy.LocalOnly("install-A","local.a"),generations);Authority=Local;module=Local;}
            else{Account=new AccountService(OwnershipPolicy.AccountScoped(simulated),generations,Identity,limits);Authority=Account;module=Account;}
            PlatformBackend.Startup=new PlatformStartup(new PlatformCapabilities(new[]{new PlatformCapability(PlatformFeature.Lifecycle,CapabilitySupport.Supported,CapabilityAvailability.Available,"mock.life"),new PlatformCapability(PlatformFeature.RewardedAds,CapabilitySupport.Supported,CapabilityAvailability.Available,"mock.ads",CapabilityConstraints.ForegroundOnly|CapabilityConstraints.UserGestureRequired,1)}),PlatformVisibility.Foreground);
            var platform=new PlatformService(PlatformBackend);Ads=new AdsService(AdBackend,Journal,ownerModuleId:ownerDependency??module.Id);
            var services=local?new[]{typeof(IClaimOwnerAuthority)}:new[]{typeof(IClaimOwnerAuthority),typeof(IAccountService)};
            Context=new GameContext(new[]{new ModuleRegistration("ads",Ads.Dependencies,()=>Ads,typeof(IAdsService)),new ModuleRegistration(module.Id,module.Dependencies,()=>module,services),new ModuleRegistration("platform",platform.Dependencies,()=>platform,typeof(IPlatformCapabilities),typeof(IPlatformLifecycle))},Cleanup);
        }
        internal FakeIdentityAttempt Attempt=>Identity.Attempts[Identity.Attempts.Count-1];internal MockRewardedAdAttempt AdAttempt=>AdBackend.Attempts[AdBackend.Attempts.Count-1];
        internal async UniTask Start()=>Check(await Context.StartAsync(Wait));
        internal IAccountSwitch Capture(){var r=Account.CaptureSwitch();Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);return r.Value;}
        internal async UniTask<IAccountSession> Login(string id="account-A"){Identity.NextOwnerId=id;var r=await Capture().WaitAsync(Wait);Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);return r.Value;}
        internal IAdOperation Ad(ClaimOwnerSnapshot owner,string claim="claim-A"){var r=Ads.Capture(new RewardedAdRequest("revive",claim,owner,true));Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);return r.Value;}
        internal UniTaskCompletionSource<Result> Held(IAccountSession session,string id="actual-work")
        {var done=new UniTaskCompletionSource<Result>();FinishActions.Add(()=>done.TrySetResult(Result.Success()));Assert.IsTrue(session.Scope.RunTask(id,_=>done.Task).IsSuccess);return done;}
        internal async UniTask Finish()
        {
            Identity.FailCleanup=Identity.ThrowCleanup=Identity.HoldCleanup=AdBackend.FailCleanup=AdBackend.HoldCleanup=false;
            foreach(var a in FinishActions)a();var close=Context.CloseAsync(Wait);
            for(var i=0;i<8;i++){foreach(var a in Identity.Attempts){a.Complete();a.CompleteCleanup();}foreach(var a in AdBackend.Attempts){a.CompleteLoad();a.CompleteShow();a.CompleteCleanup();}await UniTask.Yield();}
            var r=await close;if(!r.IsSuccess)r=await Context.RetryCleanupAsync(Cleanup,Wait);Check(r);Assert.AreEqual(0,Context.RetainedModuleCount);
        }
    }
    readonly List<Env> envs=new List<Env>();Env New(bool local=false,AccountLimits limits=null,IOwnerGenerationSource generations=null,bool simulated=true,string ownerDependency=null){var e=new Env(local,limits,generations,simulated,ownerDependency);envs.Add(e);return e;}
    static void Check(Result r)=>Assert.IsTrue(r.IsSuccess,r.IsSuccess?"":r.Error.Code);
    static async UniTask Frames(int n=5){for(var i=0;i<n;i++)await UniTask.Yield();}
    [UnityTearDown] public IEnumerator Teardown()=>UniTask.ToCoroutine(async()=>{Time.timeScale=1;foreach(var e in envs)await e.Finish();envs.Clear();});
    [UnityTest] public IEnumerator LocalOnlyPublishesOwnerWithoutAccountOrIdentity()=>UniTask.ToCoroutine(async()=>{var e=New(local:true);await e.Start();Assert.IsFalse(e.Context.TryGet<IAccountService>(out _));Assert.AreEqual(0,e.Identity.Attempts.Count);Assert.AreEqual(ClaimOwnerMode.LocalOnly,e.Authority.Mode);Assert.AreEqual("install-A",e.Authority.CurrentOwner.Value.OwnerId);});
    [UnityTest] public IEnumerator LocalAddressAndOwnerStayStableAcrossContextReopen()=>UniTask.ToCoroutine(async()=>{var g=new OwnerGenerationSequence();var a=New(local:true,generations:g);await a.Start();var old=a.Authority.CurrentOwner.Value;var address=a.Authority.AddressForCurrent("main").Value;Check(await a.Context.CloseAsync(Wait));var b=New(local:true,generations:g);await b.Start();Assert.AreEqual(address.Namespace,b.Authority.AddressForCurrent("main").Value.Namespace);Assert.AreEqual(old.OwnerId,b.Authority.CurrentOwner.Value.OwnerId);Assert.Greater(b.Authority.CurrentOwner.Value.SessionGeneration,old.SessionGeneration);});
    [UnityTest] public IEnumerator LocalCloseRevokesAuthority()=>UniTask.ToCoroutine(async()=>{var e=New(local:true);await e.Start();var old=e.Authority.CurrentOwner.Value;Check(await e.Context.CloseAsync(Wait));Assert.IsNull(e.Authority.CurrentOwner);Assert.IsFalse(e.Authority.ValidateCurrent(old).IsSuccess);Assert.IsFalse(e.Authority.AddressForCurrent("main").IsSuccess);});
    [UnityTest] public IEnumerator LocalAdsRequireBoundOwner()=>UniTask.ToCoroutine(async()=>{var e=New(local:true);await e.Start();var owner=e.Authority.CurrentOwner.Value;Assert.IsTrue((await e.Ad(owner).WaitAsync(Wait)).Value.IsCompletionObserved);var wrong=new ClaimOwnerSnapshot(owner.Mode,"other",owner.SessionGeneration,owner.StorageNamespace);Assert.IsFalse(e.Ads.Capture(new RewardedAdRequest("revive","other",wrong,true)).IsSuccess);});
    [UnityTest] public IEnumerator LocalAndAccountModesCannotBeSilentlyInterchanged()=>UniTask.ToCoroutine(async()=>{Assert.Throws<ArgumentException>(()=>new LocalOwnerService(OwnershipPolicy.AccountScoped(),new OwnerGenerationSequence()));Assert.Throws<ArgumentException>(()=>new AccountService(OwnershipPolicy.LocalOnly("install","local.a"),new OwnerGenerationSequence(),new FakeIdentityProvider()));await UniTask.Yield();});
    [UnityTest] public IEnumerator AccountStartupDoesNotAuthenticateAutomatically()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.AreEqual(AccountState.SignedOut,e.Account.State);Assert.IsNull(e.Account.Current);Assert.AreEqual(0,e.Identity.Attempts.Count);Assert.IsFalse(e.Account.AddressForCurrent("main").IsSuccess);});
    [UnityTest] public IEnumerator CapturedSwitchIsCold()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Capture();Assert.AreEqual(0,e.Identity.Attempts.Count);});
    [UnityTest] public IEnumerator ExplicitFakeIdentityPublishesAccountScopeAndOwner()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var s=await e.Login();Assert.AreEqual(ClaimOwnerMode.AccountScoped,s.Owner.Mode);Assert.AreEqual("account-A",s.Owner.OwnerId);Assert.AreEqual(ScopeKind.AccountScoped,s.Scope.Kind);Assert.IsTrue(s.IsAccepting);Assert.AreEqual(AccountState.Ready,e.Account.State);Assert.IsTrue(e.Account.ValidateCurrent(s.Owner).IsSuccess);Assert.AreEqual(1,e.Attempt.CleanupCount);});
    [UnityTest] public IEnumerator ProductionPolicyRejectsFakeAtStartup()=>UniTask.ToCoroutine(async()=>{var e=New(simulated:false);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.Identity.Attempts.Count);});
    [UnityTest] public IEnumerator SwitchWaitIsSingleUse()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var op=e.Capture();await op.WaitAsync(Wait);Assert.AreEqual("account.wait.single_use",(await op.WaitAsync(Wait)).Error.Code);});
    [UnityTest] public IEnumerator PreCanceledSwitchLeavesOldSessionActive()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();using(var c=new CancellationTokenSource()){c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await e.Capture().WaitAsync(OperationContext.Unlimited(c.Token))).Error.Kind);}Assert.AreSame(a,e.Account.Current);Assert.IsFalse(a.Scope.LifetimeCancellation.IsCancellationRequested);Assert.AreEqual(1,e.Identity.Attempts.Count);});
    [UnityTest] public IEnumerator ZeroDeadlineLeavesOldSessionActive()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(default)).Error.Kind);Assert.AreSame(a,e.Account.Current);Assert.AreEqual(1,e.Identity.Attempts.Count);});
    [UnityTest] public IEnumerator SwitchGatesOldSessionBeforeCancellationCallbacks()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();bool gated=false;using(a.Scope.LifetimeCancellation.Register(()=>{gated=!a.IsAccepting&&e.Account.Current==null&&!e.Account.ValidateCurrent(a.Owner).IsSuccess&&!a.Scope.CreateChild("too-late",ScopeKind.View).IsSuccess;})){await e.Login("account-B");}Assert.IsTrue(gated);Assert.IsFalse(a.IsAccepting);});
    [UnityTest] public IEnumerator NewAccountCanPublishWhileOldActualWorkDrains()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var held=e.Held(a);var b=await e.Login("account-B");Assert.IsTrue(a.Scope.LifetimeCancellation.IsCancellationRequested);Assert.IsTrue(b.IsAccepting);Assert.AreEqual(ScopeState.Closing,a.Scope.State);Assert.AreEqual(1,e.Account.RetiringCount);held.TrySetResult(Result.Success());await Frames();Assert.AreEqual(ScopeState.Closed,a.Scope.State);Assert.AreSame(b,e.Account.Current);});
    [UnityTest] public IEnumerator LateOldStorageWriteKeepsOriginalNamespace()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var old=e.Account.AddressForCurrent("main").Value;var store=new FakeStorageStore();var provider=new FakeStorageProvider(store);var ready=new UniTaskCompletionSource<Result>();e.FinishActions.Add(()=>ready.TrySetResult(Result.Success()));var ticket=a.Scope.RunTask("commit",async token=>{var session=provider.Create(old);await session.ReadAsync();await ready.Task;var bytes=StorageFormat.Encode(new StorageContainer(old,1,Array.Empty<StorageRecord>()),new StorageLimits()).Value;var receipt=await session.CommitAsync(new StorageWriteRequest(old,0,"",1,StorageFormat.Digest(bytes),bytes));await session.CleanupAsync(Cleanup);return receipt.Disposition==StorageCommitDisposition.Committed?Result.Success():Result.Failure(Error("test.commit"));});Assert.IsTrue(ticket.IsSuccess);var b=await e.Login("account-B");var next=e.Account.AddressForCurrent("main").Value;ready.TrySetResult(Result.Success());Check(await ticket.Value.WaitAsync(Wait));Assert.IsNotNull(store.CopyRaw(old));Assert.IsNull(store.CopyRaw(next));Assert.AreEqual(a.Owner.StorageNamespace,old.Namespace);Assert.AreEqual(b.Owner.StorageNamespace,next.Namespace);});
    [UnityTest] public IEnumerator ReturningToOwnerReusesNamespaceWithNewGeneration()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();await e.Login("account-B");var again=await e.Login();Assert.AreEqual(a.Owner.StorageNamespace,again.Owner.StorageNamespace);Assert.Greater(again.Owner.SessionGeneration,a.Owner.SessionGeneration);Assert.IsFalse(e.Account.ValidateCurrent(a.Owner).IsSuccess);});
    [UnityTest] public IEnumerator SessionBudgetBackpressuresBeforeRetiringCurrent()=>UniTask.ToCoroutine(async()=>{var e=New(limits:new AccountLimits(maxSessions:1));await e.Start();var a=await e.Login();Assert.AreEqual("account.sessions.capacity",(await e.Capture().WaitAsync(Wait)).Error.Code);Assert.AreSame(a,e.Account.Current);Assert.IsTrue(a.IsAccepting);});
    [UnityTest] public IEnumerator ConcurrentIdentityAttemptsRemainSingleFlight()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;await e.Start();var t=e.Capture().WaitAsync(Wait);Assert.AreEqual("account.switch.busy",(await e.Capture().WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Identity.Attempts.Count);e.Attempt.Complete();Assert.IsTrue((await t).IsSuccess);});
    [UnityTest] public IEnumerator CanceledResolveDoesNotPublishLateIdentity()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;await e.Start();using(var c=new CancellationTokenSource()){var t=e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(1,e.Attempt.CancelCount);Assert.AreEqual(0,e.Attempt.CleanupCount);Assert.AreEqual("account.switch.busy",(await e.Capture().WaitAsync(Wait)).Error.Code);e.Attempt.Complete();await Frames();Assert.IsNull(e.Account.Current);Assert.AreEqual(1,e.Attempt.CleanupCount);Assert.AreEqual(0,e.Account.PendingCount);}});
    [UnityTest] public IEnumerator TimeoutDoesNotReleaseActualIdentityWork()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;await e.Start();Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.AreEqual(1,e.Account.PendingCount);e.Attempt.Complete();await Frames();Assert.IsNull(e.Account.Current);});
    [UnityTest] public IEnumerator TimeScalePauseDoesNotBlockIdentityDeadline()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;await e.Start();Time.timeScale=0;Assert.AreEqual(ErrorKind.Timeout,(await e.Capture().WaitAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);e.Attempt.Complete();await Frames();Assert.IsNull(e.Account.Current);});
    [UnityTest] public IEnumerator FailedIdentityDoesNotRestoreRetiredAccount()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();e.Identity.ResolveError=Error("identity.denied",ErrorKind.PermissionDenied);Assert.AreEqual(ErrorKind.PermissionDenied,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.IsNull(e.Account.Current);Assert.IsFalse(a.IsAccepting);Assert.AreEqual(AccountState.SignedOut,e.Account.State);});
    [UnityTest] public IEnumerator IdentityIssuerAndModeMustMatchTrustedProvider()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Identity.OverrideIdentity=new BusinessIdentity("other","A",IdentityMode.Simulated);Assert.AreEqual(ErrorKind.Integrity,(await e.Capture().WaitAsync(Wait)).Error.Kind);e.Identity.OverrideIdentity=new BusinessIdentity("fake-identity","A",IdentityMode.BackendVerified);Assert.AreEqual(ErrorKind.Integrity,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.IsNull(e.Account.Current);});
    [UnityTest] public IEnumerator ProviderExceptionsAreNotWaitCancellation()=>UniTask.ToCoroutine(async()=>{foreach(var stage in new[]{"create","resolve"}){var e=New();e.Identity.ThrowCreate=stage=="create";e.Identity.ThrowResolve=stage=="resolve";await e.Start();Assert.AreEqual(ErrorKind.Provider,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.AreEqual(0,e.Account.PendingCount);}});
    [UnityTest] public IEnumerator IdentityCleanupFailureRequiresExplicitReleaseRetry()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.FailCleanup=true;await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.CleanupFailed,(await op.WaitAsync(Wait)).Error.Kind);Assert.AreEqual(AccountState.PendingCleanup,e.Account.State);Assert.IsNull(e.Account.Current);Assert.AreEqual(1,e.Account.PendingCount);e.Identity.FailCleanup=false;Check(await e.Account.RetryRetirementAsync(Cleanup,Wait));Assert.AreEqual(2,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Attempt.ResolveCount);Assert.IsNull(e.Account.Current);});
    [UnityTest] public IEnumerator CleanupExceptionRetainsIdentityAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.ThrowCleanup=true;await e.Start();Assert.AreEqual("account.cleanup.exception",(await e.Capture().WaitAsync(Wait)).Error.Code);Assert.AreEqual(1,e.Account.PendingCount);e.Identity.ThrowCleanup=false;Check(await e.Account.RetryRetirementAsync(Cleanup,Wait));});
    [UnityTest] public IEnumerator CancelFailureDoesNotDropActualIdentityAttempt()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;e.Identity.FailCancel=true;await e.Start();using(var c=new CancellationTokenSource()){var op=e.Capture();var t=op.WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();await t;Assert.IsTrue(op.CancelError.HasValue);Assert.AreEqual(1,e.Account.PendingCount);e.Attempt.Complete();await Frames();Assert.AreEqual(0,e.Account.PendingCount);}});
    [UnityTest] public IEnumerator NewSessionWaitsForActualIdentityCleanup()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldCleanup=true;await e.Start();var t=e.Capture().WaitAsync(Wait);await Frames();Assert.IsNull(e.Account.Current);Assert.AreEqual(UniTaskStatus.Pending,t.Status);e.Attempt.CompleteCleanup();Assert.IsTrue((await t).IsSuccess);});
    [UnityTest] public IEnumerator CancelDuringCleanupNeverPublishesIdentity()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldCleanup=true;await e.Start();using(var c=new CancellationTokenSource()){var t=e.Capture().WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,e.Attempt.CancelCount);e.Attempt.CompleteCleanup();await Frames();Assert.IsNull(e.Account.Current);}});
    [UnityTest] public IEnumerator OriginalIdentityErrorSurvivesCleanupFailure()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.ResolveError=Error("original.denied",ErrorKind.PermissionDenied);e.Identity.FailCleanup=true;await e.Start();var op=e.Capture();Assert.AreEqual("original.denied",(await op.WaitAsync(Wait)).Error.Code);Assert.AreEqual(ErrorKind.CleanupFailed,op.CleanupError.Value.Kind);});
    [UnityTest] public IEnumerator RetiredScopeFailureDoesNotBlockNewAccountButRequiresRetry()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var release=new ToggleCleanup();e.FinishActions.Add(()=>release.Fail=false);a.Scope.Cleanup.Register(release);var b=await e.Login("account-B");await Frames();Assert.AreEqual(ScopeState.CleanupFailed,a.Scope.State);Assert.IsTrue(b.IsAccepting);Assert.AreEqual(1,release.Count);release.Fail=false;Check(await e.Account.RetryRetirementAsync(Cleanup,Wait));Assert.AreEqual(2,release.Count);Assert.AreEqual(ScopeState.Closed,a.Scope.State);Assert.AreSame(b,e.Account.Current);});
    [UnityTest] public IEnumerator CloseDoesNotImplicitlyRetryRetiredFailure()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var release=new ToggleCleanup();e.FinishActions.Add(()=>release.Fail=false);a.Scope.Cleanup.Register(release);await e.Login("account-B");await Frames();Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);Assert.AreEqual(1,release.Count);release.Fail=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,release.Count);});
    [UnityTest] public IEnumerator CloseWaitsActualResolveAndNeverPublishesLateAccount()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.HoldResolve=true;await e.Start();var t=e.Capture().WaitAsync(Wait);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.AreEqual(0,e.Attempt.CleanupCount);e.Attempt.Complete();Check(await close);Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.IsNull(e.Account.Current);Assert.AreEqual(AccountState.Closed,e.Account.State);});
    [UnityTest] public IEnumerator CloseWaitsRetiredActualWork()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var held=e.Held(a);await e.Login("account-B");var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(UniTaskStatus.Pending,close.Status);Assert.Greater(e.Context.RetainedModuleCount,0);held.TrySetResult(Result.Success());Check(await close);Assert.AreEqual(ScopeState.Closed,a.Scope.State);});
    [UnityTest] public IEnumerator CloseObserverTimeoutDoesNotEraseOldSession()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var held=e.Held(a);Assert.AreEqual(ErrorKind.Timeout,(await e.Context.CloseAsync(new OperationContext(default,TimeSpan.FromMilliseconds(5)))).Error.Kind);Assert.IsFalse(a.IsAccepting);Assert.AreEqual(ScopeState.Closing,a.Scope.State);held.TrySetResult(Result.Success());Check(await e.Context.CloseAsync(Wait));});
    [UnityTest] public IEnumerator FailedIdentityCleanupRetainsModuleAcrossClose()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.FailCleanup=true;await e.Start();await e.Capture().WaitAsync(Wait);Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);Assert.AreEqual(1,e.Attempt.CleanupCount);e.Identity.FailCleanup=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,e.Attempt.CleanupCount);Assert.AreEqual(1,e.Attempt.ResolveCount);});
    [UnityTest] public IEnumerator AdsRejectOldOwnerBeforeShowAfterSwitch()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();var ad=e.Ad(a.Owner);await e.Login("account-B");Assert.IsFalse((await ad.WaitAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.AdBackend.Attempts.Count);Assert.IsFalse(e.Ads.Capture(new RewardedAdRequest("revive","late",a.Owner,true)).IsSuccess);});
    [UnityTest] public IEnumerator AdsLoadingForOldOwnerCannotShowIntoNewAccount()=>UniTask.ToCoroutine(async()=>{var e=New();e.AdBackend.HoldLoad=true;await e.Start();var a=await e.Login();var ad=e.Ad(a.Owner);var t=ad.WaitAsync(Wait);await e.Login("account-B");e.AdAttempt.CompleteLoad();Assert.IsFalse((await t).IsSuccess);Assert.AreEqual(0,e.AdAttempt.ShowCount);Assert.AreEqual(a.Owner.OwnerId,ad.Receipt.Owner.OwnerId);});
    [UnityTest] public IEnumerator VisibleOldAccountAdCompletesOnlyForOriginalOwner()=>UniTask.ToCoroutine(async()=>{var e=New();e.AdBackend.AutoCallbacks=false;e.AdBackend.HoldShow=true;await e.Start();var a=await e.Login();var ad=e.Ad(a.Owner);var t=ad.WaitAsync(OperationContext.Unlimited(a.Scope.LifetimeCancellation));var native=e.AdAttempt;var b=await e.Login("account-B");Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.AreEqual(0,native.CleanupCount);native.Publish(AdCallbackKind.Started);native.Publish(AdCallbackKind.Completed);native.Publish(AdCallbackKind.Closed);native.CompleteShow();await Frames();Assert.IsTrue(ad.Receipt.IsCompletionObserved);Assert.IsTrue(ad.Receipt.Owner.SameAs(a.Owner));Assert.IsFalse(ad.Receipt.Owner.SameAs(b.Owner));Assert.AreEqual(1,e.Journal.PendingCount);Assert.AreEqual(1,native.CleanupCount);});
    [UnityTest] public IEnumerator NewAccountAdWaitsOldVisibleAdActualRelease()=>UniTask.ToCoroutine(async()=>{var e=New();e.AdBackend.HoldShow=true;await e.Start();var a=await e.Login();var first=e.Ad(a.Owner);var t1=first.WaitAsync(Wait);var old=e.AdAttempt;var b=await e.Login("account-B");var t2=e.Ad(b.Owner,"claim-B").WaitAsync(Wait);await Frames();Assert.AreEqual(1,e.AdBackend.Attempts.Count);Assert.AreEqual(ErrorKind.Canceled,(await t1).Error.Kind);Assert.AreEqual(0,old.CleanupCount);old.CompleteShow();await Frames();Assert.IsTrue(first.Receipt.Owner.SameAs(a.Owner));Assert.AreEqual(2,e.AdBackend.Attempts.Count);e.AdAttempt.CompleteShow();Assert.IsTrue((await t2).Value.Owner.SameAs(b.Owner));});
    [UnityTest] public IEnumerator AccountAdClaimCannotBeReassignedToNewOwner()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var a=await e.Login();await e.Ad(a.Owner).WaitAsync(Wait);var b=await e.Login("account-B");Assert.AreEqual(ErrorKind.Integrity,(await e.Ad(b.Owner).WaitAsync(Wait)).Error.Kind);Assert.AreEqual(1,e.AdBackend.Attempts.Count);});
    [UnityTest] public IEnumerator AdsOwnerDependencyMustResolveExplicitly()=>UniTask.ToCoroutine(async()=>{var e=New(ownerDependency:"missing-owner");Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.AdBackend.Attempts.Count);});
    [UnityTest] public IEnumerator ContextRebuildUsesNewGenerationAndIsolatesOldSession()=>UniTask.ToCoroutine(async()=>{var g=new OwnerGenerationSequence();var old=New(generations:g);await old.Start();var a=await old.Login();Check(await old.Context.CloseAsync(Wait));var next=New(generations:g);await next.Start();var b=await next.Login();Assert.AreNotEqual(a.ContextGeneration,b.ContextGeneration);Assert.Greater(b.Owner.SessionGeneration,a.Owner.SessionGeneration);Assert.IsFalse(next.Account.ValidateCurrent(a.Owner).IsSuccess);Assert.IsFalse(a.IsAccepting);});
    [UnityTest] public IEnumerator LocalSlotRejectsTraversalAndAccountSlotRejectsTraversal()=>UniTask.ToCoroutine(async()=>{var local=New(local:true);await local.Start();Assert.AreEqual(ErrorKind.InvalidArgument,local.Authority.AddressForCurrent("../slot").Error.Kind);var e=New();await e.Start();await e.Login();Assert.AreEqual(ErrorKind.InvalidArgument,e.Account.AddressForCurrent("../slot").Error.Kind);});
    [UnityTest] public IEnumerator GenerationExhaustionFailsWithoutPublishingAccount()=>UniTask.ToCoroutine(async()=>{var e=New(generations:new OwnerGenerationSequence(long.MaxValue));await e.Start();Assert.AreEqual(ErrorKind.Integrity,(await e.Capture().WaitAsync(Wait)).Error.Kind);Assert.IsNull(e.Account.Current);Assert.AreEqual(1,e.Attempt.CleanupCount);});
    [UnityTest] public IEnumerator LocalGenerationExhaustionFailsStartup()=>UniTask.ToCoroutine(async()=>{var e=New(local:true,generations:new OwnerGenerationSequence(long.MaxValue));Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(e.Authority.CurrentOwner);});
    [UnityTest] public IEnumerator ColdOperationCapacityRecoversAfterCanceledWait()=>UniTask.ToCoroutine(async()=>{var e=New(limits:new AccountLimits(maxOperations:1));await e.Start();var op=e.Capture();Assert.AreEqual(ErrorKind.Unavailable,e.Account.CaptureSwitch().Error.Kind);await op.WaitAsync(default);Assert.IsTrue(e.Account.CaptureSwitch().IsSuccess);});
    [UnityTest] public IEnumerator RetryIsSingleFlightAndCancellationOnlyEndsItsObserver()=>UniTask.ToCoroutine(async()=>{var e=New();e.Identity.FailCleanup=true;await e.Start();await e.Capture().WaitAsync(Wait);e.Identity.FailCleanup=false;e.Identity.HoldCleanup=true;using(var c=new CancellationTokenSource()){var first=e.Account.RetryRetirementAsync(Cleanup,OperationContext.Unlimited(c.Token));var join=e.Account.RetryRetirementAsync(Cleanup,Wait);c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await first).Error.Kind);Assert.AreEqual(2,e.Attempt.CleanupCount);e.Attempt.CompleteCleanup();Check(await join);Assert.AreEqual(1,e.Attempt.ResolveCount);Assert.IsNull(e.Account.Current);}});
    [UnityTest] public IEnumerator RepeatedSwitchAndCloseReturnDiagnosticsToZero()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();for(var i=0;i<8;i++)await e.Login("account-"+i);Check(await e.Context.CloseAsync(Wait));var d=e.Account.ReadDiagnostics();Assert.AreEqual(0,d.ActiveScopes);Assert.AreEqual(0,d.PendingOperations);Assert.AreEqual(0,d.FailedCleanup);Assert.IsNull(e.Authority.CurrentOwner);});
    [UnityTest] public IEnumerator AccountAuthorityRejectsForgedNamespaceAndGeneration()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();var s=await e.Login();var o=s.Owner;Assert.IsFalse(e.Account.ValidateCurrent(new ClaimOwnerSnapshot(o.Mode,o.OwnerId,o.SessionGeneration,"account.wrong")).IsSuccess);Assert.IsFalse(e.Account.ValidateCurrent(new ClaimOwnerSnapshot(o.Mode,o.OwnerId,o.SessionGeneration+1,o.StorageNamespace)).IsSuccess);Assert.IsTrue(e.Account.ValidateCurrent(o).IsSuccess);});
    [UnityTest] public IEnumerator CancellationDuringColdFactoryCannotStartIdentityIo()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();using(var c=new CancellationTokenSource()){e.Identity.OnCreate=c.Cancel;Assert.AreEqual(ErrorKind.Canceled,(await e.Capture().WaitAsync(OperationContext.Unlimited(c.Token))).Error.Kind);Assert.AreEqual(0,e.Attempt.ResolveCount);Assert.AreEqual(1,e.Attempt.CleanupCount);Assert.IsNull(e.Account.Current);}});
    [UnityTest] public IEnumerator GenerationReentryAndExceptionsCannotPublishLateOwners()=>UniTask.ToCoroutine(async()=>{Env e=null;e=New(generations:new Generation(()=>{e.Account.StopAsync(Cleanup);return Result<long>.Success(1);}));await e.Start();Assert.IsFalse((await e.Capture().WaitAsync(Wait)).IsSuccess);Assert.IsNull(e.Account.Current);var failed=New(generations:new Generation(()=>throw new InvalidOperationException()));await failed.Start();Assert.AreEqual("account.generation.exception",(await failed.Capture().WaitAsync(Wait)).Error.Code);Assert.AreEqual(0,failed.Account.PendingCount);Env local=null;local=New(local:true,generations:new Generation(()=>{local.Local.StopAsync(Cleanup);return Result<long>.Success(1);}));Assert.IsFalse((await local.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(local.Authority.CurrentOwner);});

    [UnityTest] public IEnumerator SameFrameOwnerChangeCannotPublishOldObserverSuccess()=>UniTask.ToCoroutine(async()=>{var e=New();e.AdBackend.HoldShow=true;await e.Start();var a=await e.Login();var ad=e.Ad(a.Owner);var t=ad.WaitAsync(Wait);await Frames();await e.Login("account-B");e.AdAttempt.CompleteShow();Assert.AreEqual(ErrorKind.Canceled,(await t).Error.Kind);Assert.IsTrue(ad.Receipt.IsCompletionObserved);Assert.IsTrue(ad.Receipt.Owner.SameAs(a.Owner));});

